// Descriptor kinds are permanent versioned semantics. Unknown kinds never borrow current art.
export function feedingBoardArt(item,{small=false,food=false}={}){
 const art=item?.art, draw=food?foods:animals;
 if(art?.version!==1||!Object.hasOwn(draw,art.kind))return `<span class="fb-art-fallback"><span>The original picture description is shown here. Your earlier answer is retained.</span> ${esc(art?.description||item?.name||item?.label||'')}</span>`;
 const body=typeof draw[art.kind]==='function'?draw[art.kind]():draw[art.kind];
 return `<span class="fb-art${small?' fb-art-small':''}${food?' fb-food-art':''}" data-fb-art="${esc(art.kind)}"><svg viewBox="0 0 ${food?'210 180':'280 190'}" aria-hidden="true" focusable="false"><g stroke="#485548" stroke-width="2.8" stroke-linecap="round" stroke-linejoin="round">${body}</g></svg>${small?'':`<span class="fb-art-description">${esc(art.description)}</span>`}</span>`;
}
